251	    /**
252	     * Fixed city-to-region lookup used to validate an owner's postcode. Mirrors the presentation
253	     * locality table (Sydney->NSW, Melbourne->VIC, Brisbane->QLD).
254	     */
255	    private static final Map<String, String> CITY_REGION = Map.of(
256	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
257	
258	    /** Region -> inclusive 4-digit postcode range {low, high}. */
259	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
260	        "NSW", new int[] {2000, 2099},
261	        "VIC", new int[] {3000, 3099},
262	        "QLD", new int[] {4000, 4099});
263	
264	    /**
265	     * Rejects saving {@code owner} when it carries a postcode that is out of range for its city's
266	     * region. The postcode is optional: a {@code null} postcode is left untouched. When present it
267	     * is assumed to already be four digits (enforced by request validation); if the owner's city has
268	     * a known region (see {@link #CITY_REGION}), the postcode must fall within that region's range
269	     * ({@link #REGION_POSTCODES}). A city with no known region accepts any 4-digit postcode.
270	     *
271	     * @throws InvalidPostcodeException if the postcode is out of range for the city's region
272	     */
273	    private void assertPostcodeValid(Owner owner) {
274	        String postcode = owner.getPostcode();
275	        if (postcode == null) {
276	            return;
277	        }
278	        String region = CITY_REGION.get(owner.getCity());
279	        int[] range = region == null ? null : REGION_POSTCODES.get(region);
280	        if (range == null) {
281	            return;
282	        }
283	        int value = Integer.parseInt(postcode);
284	        if (value < range[0] || value > range[1]) {
285	            throw new InvalidPostcodeException(postcode, owner.getCity(), region);
286	        }
287	    }
