289	    @Override
290	    @Transactional
291	    public void saveOwner(Owner owner) throws DataAccessException {
292	        assertPostcodeValid(owner);
293	        if (owner.getTelephone() != null) {
294	            owner.setTelephone(normalizeTelephone(owner.getTelephone()));
295	        }
296	        if (owner.getEmail() != null) {
297	            owner.setEmail(normalizeEmail(owner.getEmail()));
298	        }
299	        if (owner.getAddress() != null) {
300	            owner.setAddress(normalizeAddress(owner.getAddress()));
301	        }
302	        LocalDate effectiveDate = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
303	        owner.setRegistrationDate(rollToBusinessDay(effectiveDate));
304	        if (owner.getCustomerCode() == null) {
305	            owner.setCustomerCode(generateCustomerCode(owner));
306	        }
307	        boolean creating = owner.isNew();
308	        if (creating) {
309	            owner.setNamesakeCount(countNamesakes(owner));
310	            assertDailyCapacity(owner);
311	            assertCityCapacity(owner);
312	        }
313	        List<Owner> household = findHouseholdMembers(owner);
314	        assignHousehold(owner, household);
315	        assertIdentityUnique(owner);
316	        ownerRepository.save(owner);
317	        populateHouseholdSize(owner);
318	        if (creating) {
319	            AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
320	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
321	                owner.getMembershipLevel());
322	        }
323	    }
324	
325	    /**
326	     * Build a {@code customerCode} formatted {@code '<CITY3>-<LAST3>-<NNNN>'} where CITY3 is the
327	     * upper-cased first three letters of the owner's city, LAST3 the upper-cased first three
328	     * letters of {@code lastName}, and NNNN is a per-city 4-digit zero-padded sequence equal to
329	     * one more than the number of owners already in that city.
330	     */
331	    private String generateCustomerCode(Owner owner) {
332	        String cityPrefix = prefix3(owner.getCity());
333	        String lastNamePrefix = prefix3(owner.getLastName());
334	        long sequence = countOwnersInCity(owner.getCity()) + 1L;
335	        return String.format("%s-%s-%04d", cityPrefix, lastNamePrefix, sequence);
336	    }
337	
338	    private static String prefix3(String value) {
339	        return value.substring(0, Math.min(3, value.length())).toUpperCase(Locale.ROOT);
340	    }
341	
342	    /** Maximum number of owners permitted in a single city. */
343	    private static final long CITY_OWNER_LIMIT = 50L;
344	
345	    /**
346	     * Rejects creating {@code owner} when its city already contains {@link #CITY_OWNER_LIMIT} or
347	     * more owners, so no city can grow beyond the capacity limit.
348	     *
349	     * @throws CityOwnerLimitException if the owner's city is already at capacity
350	     */
351	    private void assertCityCapacity(Owner owner) {
352	        if (owner.getCity() == null) {
353	            return;
354	        }
355	        if (countOwnersInCity(owner.getCity()) >= CITY_OWNER_LIMIT) {
356	            throw new CityOwnerLimitException(owner.getCity(), CITY_OWNER_LIMIT);
357	        }
358	    }
359	
360	    /**
361	     * Rolls {@code date} forward to the next business day when it falls on a weekend: a Saturday or
362	     * Sunday becomes the following Monday. Business days (Monday to Friday) are returned unchanged.
363	     */
364	    private static LocalDate rollToBusinessDay(LocalDate date) {
365	        switch (date.getDayOfWeek()) {
366	            case SATURDAY:
367	                return date.plusDays(2);
368	            case SUNDAY:
369	                return date.plusDays(1);
370	            default:
371	                return date;
372	        }
373	    }
374	
375	    /** Maximum number of owners permitted to be registered on a single day. */
376	    private static final long DAILY_OWNER_LIMIT = 100L;
377	
378	    /** More than this many owners registered on a single day raises the bulk-signup warning. */
379	    private static final long BULK_SIGNUP_THRESHOLD = 80L;
380	
381	    /**
382	     * Reports whether more than {@link #BULK_SIGNUP_THRESHOLD} owners have already been registered
383	     * today, reusing the same daily accumulation as the per-day create limit ({@link
384	     * #assertDailyCapacity}).
385	     */
386	    @Override
387	    @Transactional(readOnly = true)
388	    public boolean isBulkSignupWarningActive() throws DataAccessException {
389	        return countOwnersRegisteredOn(LocalDate.now()) > BULK_SIGNUP_THRESHOLD;
390	    }
391	
392	    /**
393	     * Rejects creating {@code owner} when its {@code registrationDate} (defaulted to today for a new
394	     * owner) already has {@link #DAILY_OWNER_LIMIT} or more owners registered, so no more than that
395	     * many owners can be created on any single day.
396	     *
397	     * @throws DailyOwnerLimitException if the owner's registration day is already at capacity
398	     */
399	    private void assertDailyCapacity(Owner owner) {
400	        LocalDate date = owner.getRegistrationDate();
401	        if (date == null) {
402	            return;
403	        }
404	        if (countOwnersRegisteredOn(date) >= DAILY_OWNER_LIMIT) {
405	            throw new DailyOwnerLimitException(date, DAILY_OWNER_LIMIT);
406	        }
407	    }
