409	    private long countOwnersRegisteredOn(LocalDate date) {
410	        return ownerRepository.findAll().stream()
411	                .filter(existing -> date.equals(existing.getRegistrationDate()))
412	                .count();
413	    }
414	
415	    private long countOwnersInCity(String city) {
416	        String normalized = normalizeHouseholdValue(city);
417	        return ownerRepository.findAll().stream()
418	                .filter(existing -> normalized.equals(normalizeHouseholdValue(existing.getCity())))
419	                .count();
420	    }
421	
422	    /**
423	     * Counts the existing owners that share both {@code firstName} and {@code lastName} with the
424	     * given new {@code owner}, compared case-insensitively (with incidental whitespace collapsed).
425	     * The owner being created is not itself persisted yet, so the result is the number of namesakes
426	     * that already existed before this create.
427	     */
428	    private int countNamesakes(Owner owner) {
429	        String firstName = normalizeHouseholdValue(owner.getFirstName());
430	        String lastName = normalizeHouseholdValue(owner.getLastName());
431	        int count = 0;
432	        for (Owner existing : ownerRepository.findAll()) {
433	            if (!existing.getId().equals(owner.getId())
434	                    && firstName.equals(normalizeHouseholdValue(existing.getFirstName()))
435	                    && lastName.equals(normalizeHouseholdValue(existing.getLastName()))) {
436	                count++;
437	            }
438	        }
439	        return count;
440	    }
441	
442	    private static String normalizeEmail(String email) {
443	        return email == null ? null : email.toLowerCase(Locale.ROOT);
444	    }
445	
446	    /** Common street-type abbreviations expanded during address normalization. */
447	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
448	        "ST", "STREET",
449	        "RD", "ROAD",
450	        "AVE", "AVENUE");
451	
452	    /**
453	     * Canonicalizes a postal address: trims and collapses runs of whitespace into a single space,
454	     * upper-cases, and expands common street-type abbreviations (ST->STREET, RD->ROAD, AVE->AVENUE)
455	     * as whole words. Returns {@code null} for a {@code null} input and an empty string when the
456	     * address is blank once whitespace is stripped, so the required-field check sees the normalized
457	     * form.
458	     */
459	    private static String normalizeAddress(String address) {
460	        if (address == null) {
461	            return null;
462	        }
463	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
464	        if (collapsed.isEmpty()) {
465	            return "";
466	        }
467	        String[] tokens = collapsed.split(" ");
468	        StringBuilder sb = new StringBuilder(collapsed.length());
469	        for (int i = 0; i < tokens.length; i++) {
470	            if (i > 0) {
471	                sb.append(' ');
472	            }
473	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
474	        }
475	        return sb.toString();
476	    }
477	
478	    private static String normalizeTelephone(String telephone) {
479	        return telephone == null ? null : E164Telephone.toE164(telephone);
480	    }
481	
482	    /**
483	     * Rejects saving {@code owner} when its whole {@link Owner#getIdentityKey() identity key} equals
484	     * that of another owner. This single check consolidates the former separate telephone, email and
485	     * household duplicate rules: because the normalized telephone is part of the key, two members of
486	     * the same household (same {@code householdId}) with different telephones have different keys and
487	     * are both allowed — only an exact full-key match is a duplicate.
488	     *
489	     * @throws DuplicateIdentityException if another owner already has the same identity key
490	     */
491	    private void assertIdentityUnique(Owner owner) {
492	        String identityKey = owner.getIdentityKey();
493	        for (Owner existing : ownerRepository.findAll()) {
494	            if (!existing.getId().equals(owner.getId()) && identityKey.equals(existing.getIdentityKey())) {
495	                throw new DuplicateIdentityException(identityKey);
496	            }
497	        }
498	    }
499	
500	    /**
501	     * Returns the existing owners that share both {@code lastName} (compared case-insensitively with
502	     * collapsed whitespace) and the normalized {@code address} with a new {@code owner} — i.e. the
503	     * members of the household it would join. Returns an empty list for an update to an existing
504	     * owner or when either household value is blank, so household rules only apply to genuine new
505	     * members.
506	     */
507	    private List<Owner> findHouseholdMembers(Owner owner) {
508	        if (!owner.isNew()) {
509	            return List.of();
510	        }
511	        String lastName = normalizeHouseholdValue(owner.getLastName());
512	        String address = normalizeHouseholdAddress(owner.getAddress());
513	        if (lastName.isEmpty() || address.isEmpty()) {
514	            return List.of();
515	        }
516	        List<Owner> household = new ArrayList<>();
517	        for (Owner existing : ownerRepository.findAll()) {
518	            if (!existing.getId().equals(owner.getId())
519	                    && lastName.equals(normalizeHouseholdValue(existing.getLastName()))
520	                    && address.equals(normalizeHouseholdAddress(existing.getAddress()))) {
521	                household.add(existing);
522	            }
523	        }
524	        return household;
525	    }
526	
527	    /**
528	     * Assigns household membership when {@code owner} joins a non-empty {@code household}: the new
529	     * owner and every matching existing member that lacks one are given the same stable
530	     * {@code householdId}, and any updated existing members are persisted. No-op when the household
531	     * is empty.
532	     */
533	    private void assignHousehold(Owner owner, List<Owner> household) {
534	        if (household.isEmpty()) {
535	            return;
536	        }
537	        String householdId = resolveHouseholdId(owner, household);
538	        owner.setHouseholdId(householdId);
539	        for (Owner existing : household) {
540	            if (existing.getHouseholdId() == null || existing.getHouseholdId().isBlank()) {
541	                existing.setHouseholdId(householdId);
542	                ownerRepository.save(existing);
543	            }
544	        }
545	    }
546	
547	    /**
548	     * Stamps {@code owner} with the number of owners sharing its {@code householdId} (see {@link
549	     * Owner#getHouseholdSize()}), so presentation code can derive the membership tier without
550	     * reaching into the data store. A {@code null} owner or one without a household id is left at
551	     * size 0.
552	     */
553	    private void populateHouseholdSize(Owner owner) {
554	        if (owner == null) {
555	            return;
556	        }
557	        String householdId = owner.getHouseholdId();
558	        if (householdId == null || householdId.isBlank()) {
559	            owner.setHouseholdSize(0);
560	            return;
561	        }
562	        int count = 0;
563	        for (Owner existing : ownerRepository.findAll()) {
564	            if (householdId.equals(existing.getHouseholdId())) {
565	                count++;
566	            }
567	        }
568	        owner.setHouseholdSize(count);
569	    }
570	
571	    /**
572	     * Stamps every owner in {@code owners} with its household size in a single pass over the data
573	     * store, so a list/page of owners is counted without a per-owner query.
574	     *
575	     * @see #populateHouseholdSize(Owner)
576	     */
577	    private void populateHouseholdSizes(Collection<Owner> owners) {
578	        if (owners.isEmpty()) {
579	            return;
580	        }
581	        Map<String, Integer> sizes = new HashMap<>();
582	        for (Owner existing : ownerRepository.findAll()) {
583	            String householdId = existing.getHouseholdId();
584	            if (householdId != null && !householdId.isBlank()) {
585	                sizes.merge(householdId, 1, Integer::sum);
586	            }
587	        }
588	        for (Owner owner : owners) {
589	            String householdId = owner.getHouseholdId();
590	            owner.setHouseholdSize(householdId == null ? 0 : sizes.getOrDefault(householdId, 0));
591	        }
592	    }
593	
594	    /**
595	     * Returns the {@code householdId} shared by a household: the first non-blank identifier already
596	     * carried by an existing member, or otherwise a freshly derived stable identifier for the
597	     * joining {@code owner}'s normalized lastName and address.
598	     */
599	    private String resolveHouseholdId(Owner owner, List<Owner> household) {
600	        for (Owner existing : household) {
601	            if (existing.getHouseholdId() != null && !existing.getHouseholdId().isBlank()) {
602	                return existing.getHouseholdId();
603	            }
604	        }
605	        return generateHouseholdId(normalizeHouseholdValue(owner.getLastName()),
606	            normalizeHouseholdAddress(owner.getAddress()));
607	    }
608	
609	    /**
610	     * Derives a stable {@code householdId} formatted {@code 'HH-<12 upper-hex>'} from the SHA-256
611	     * digest of the normalized {@code lastName} and {@code address}, so all owners in the same
612	     * household deterministically share the same identifier.
613	     */
614	    private static String generateHouseholdId(String lastName, String address) {
615	        try {
616	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
617	            byte[] hash = digest.digest((lastName + "\u0000" + address).getBytes(StandardCharsets.UTF_8));
618	            StringBuilder sb = new StringBuilder();
619	            for (int i = 0; i < 6; i++) {
620	                sb.append(String.format("%02X", hash[i]));
621	            }
622	            return "HH-" + sb;
623	        } catch (NoSuchAlgorithmException e) {
624	            throw new IllegalStateException("SHA-256 not available", e);
625	        }
626	    }
627	
628	    /**
629	     * Normalizes a household comparison value by trimming, collapsing runs of whitespace into a
